// Copies core's built-in icon data (packages/core/src/icons/data.ts) into
// src/icons/data.ts, so the native package draws the same icons without
// depending on core. `--check` fails while the copy is stale.
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const source = join(root, "../core/src/icons/data.ts");
const target = join(root, "src/icons/data.ts");

const copy = readFileSync(source, "utf8")
  .replace(
    "// Generated by scripts/generate-icons.mjs — do not edit by hand.",
    "// Copied from packages/core/src/icons/data.ts by scripts/sync-icons.mjs — do not edit by hand.",
  )
  .replace("./ATTRIBUTION.md", "packages/core/src/icons/ATTRIBUTION.md")
  .replace(/from "\.\/renderIcon(\.js)?"/, 'from "./types"');

if (process.argv.includes("--check")) {
  let current = "";
  try {
    current = readFileSync(target, "utf8");
  } catch {}
  if (current !== copy) {
    console.error("src/icons/data.ts is stale: run `pnpm sync:icons`.");
    process.exit(1);
  }
} else {
  writeFileSync(target, copy);
  console.log("src/icons/data.ts copied from core");
}
